// This file is generated by AI.

// 未保存更改的三选一 (保存 / 不保存 / 取消)。
//
// 与 `confirm.ts` 同一套路: 调用方给出"确认之后要做什么", 这里决定要不要先问, 并在用户选了
// "保存"时先把脏文档落盘 (关选项卡 / 关项目 / 关窗口 / 生成快照前都走这里)。

import { noteDiskContent } from './editor/disk-sync.svelte';
import { fs } from './lib/fs';
import { useAppStore } from './state/store.svelte';

export type UnsavedChoice = 'save' | 'discard' | 'cancel';

interface PendingClose {
  action: () => void;
  /** 只看这份文档是否脏; 省略则看全部文档 */
  path?: string;
  message?: string;
}

/** 当前待处理的请求; `null` 表示没有。 */
let pendingClose: PendingClose | null = null;

/** 系统关闭按钮 (窗口右上角的叉 / Alt+F4) 是否已被放行; 由 `+layout.svelte` 的 `onCloseRequested` 读取。 */
let allowWindowClose = false;

/** 读放行标志 (给 `onCloseRequested` 用)。 */
export function windowCloseAllowed(): boolean {
  return allowWindowClose;
}

/**
 * 执行一个动作, 但先处理未保存的更改。没有脏文档时**直接执行**, 不弹窗 —— 弹一个"要不要保存"
 * 而实际上没什么可保存的, 只会让人以为自己漏了什么。
 */
export function confirmClose(action: () => void, path?: string, message?: string): void {
  if (!hasDirty(path)) {
    action();
    return;
  }
  pendingClose = { action, path, message };
  useAppStore.getState().setUnsavedDialog(true);
}

/** 界面用的提示语 (可以为空, 那时用默认文案)。 */
export function pendingUnsavedMessage(): string | undefined {
  return pendingClose?.message;
}

/** 界面回执。 */
export function resolveUnsaved(choice: UnsavedChoice): void {
  const current = pendingClose;
  pendingClose = null;
  useAppStore.getState().setUnsavedDialog(false);
  if (!current) return;
  if (choice === 'cancel') return;
  if (choice === 'discard') {
    current.action();
    return;
  }
  void saveDirty(current.path).then(current.action);
}

/**
 * 请求关闭窗口。
 *
 * 标题栏的关闭按钮与系统关闭按钮都走这里 —— 两条路径各自实现一遍, 迟早出现"点标题栏的叉
 * 不问、点系统的叉才问"这类不一致。
 *
 * 应用内确认通过后置 `allowWindowClose`, 使 `onCloseRequested` 再收到事件时直接放行。
 */
export function requestClose(): void {
  const dirty = useAppStore.getState().documents.some((doc) => doc.dirty);
  if (!dirty) {
    allowWindowClose = true;
    void closeWindow();
    return;
  }
  confirmClose(() => {
    allowWindowClose = true;
    void closeWindow();
  });
}

async function closeWindow(): Promise<void> {
  const { getCurrentWindow } = await import('@tauri-apps/api/window');
  await getCurrentWindow().close();
}

function hasDirty(path?: string): boolean {
  const documents = useAppStore.getState().documents;
  return path ? documents.some((doc) => doc.path === path && doc.dirty) : documents.some((doc) => doc.dirty);
}

/**
 * 把脏文档写盘。这里**直接写盘**, 没有走 `editor/document-saver.ts` 的队列 —— 调用点都在
 * "用户已经决定保存并即将关闭/切换"的时刻, 编辑器此时不会再发起自动保存; 代价是失去了队列的
 * "内容变了就不回执"保护, 所以回执时必须重新核对内容。内容以**内存里那份**为准。
 */
async function saveDirty(path?: string): Promise<void> {
  const store = useAppStore.getState();
  const targets = store.documents.filter((doc) => doc.dirty && (!path || doc.path === path));
  await Promise.all(
    targets.map(async (doc) => {
      try {
        await fs.writeText(doc.path, doc.content);
      } catch (error) {
        console.error('保存文档失败', doc.path, error);
        // 写失败就不清脏标记: 让用户还能再试一次, 而不是以为已经存好了
        return;
      }
      /*
       * 磁盘上现在就是这一份: 记下基准。不记的话, 这次"关窗前保存"会被磁盘变更检测当成外部
       * 修改而弹一次冲突 (用户刚点过保存, 却被告知文件被外部改过)。
       */
      noteDiskContent(doc.path, doc.content);
      // 落盘期间内容可能又被改过; 变了就不清脏标记
      const latest = useAppStore.getState().documents.find((item) => item.path === doc.path);
      if (!latest || latest.content !== doc.content) return;
      useAppStore.getState().updateDocument(doc.path, { dirty: false });
    })
  );
}
